  const [audience, setAudience] = useState<Audience>("future");
  const [openDepartment, setOpenDepartment] = useState(0);
  const [courseLevel, setCourseLevel] = useState("All programmes");
  const [courseDepartment, setCourseDepartment] = useState("All departments");
  const [courseMode, setCourseMode] = useState("All study modes");
  const [courseQuery, setCourseQuery] = useState("");
  const [selectedCourse, setSelectedCourse] = useState<(typeof courses)[number] | null>(null);
  const [showAllNews, setShowAllNews] = useState(false);
  const [savedEvent, setSavedEvent] = useState<string | null>(null);
