  const [newsletterJoined, setNewsletterJoined] = useState(false);

  useEffect(() => {
    if (!searchOpen && !selectedCourse) return;
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        if (searchOpen) {
          setSearchOpen(false);
          setSearch("");
        } else {
          setSelectedCourse(null);
        }
      }
    };
    document.addEventListener("keydown", handleEscape);
    return () => document.removeEventListener("keydown", handleEscape);
  }, [searchOpen, selectedCourse]);

  const searchResults = useMemo(() => {
    if (!search.trim()) return [];
    const query = search.toLowerCase();
    return searchIndex.filter((item) => `${item.title} ${item.category} ${item.keywords}`.includes(query));
  }, [search]);

  const visibleCourses = useMemo(() => {
    const query = courseQuery.trim().toLowerCase();
    return courses.filter((course) => {
      const matchesLevel = courseLevel === "All programmes" || course.level === courseLevel;
      const matchesDepartment = courseDepartment === "All departments" || course.department === courseDepartment;
      const matchesMode = courseMode === "All study modes" || course.mode === courseMode;
      const matchesQuery = !query || `${course.title} ${course.department} ${course.level} ${course.pathway}`.toLowerCase().includes(query);
      return matchesLevel && matchesDepartment && matchesMode && matchesQuery;
    });
  }, [courseDepartment, courseLevel, courseMode, courseQuery]);

